mapper.select:
SELECT 
FROM iam_client_session cs
WHERE cs.user_session_id = #{userSessionId}
  AND cs.client_id = #{clientId}
  AND cs.deleted = FALSE

mapper.update:
UPDATE iam_client_session cs
SET deleted = TRUE, updated_time = CURRENT_TIMESTAMP
FROM iam_user_session us
WHERE us.id = cs.user_session_id
  AND us.user_id = #{userId}
  AND us.realm_id = #{realmId}
  AND cs.client_id = #{clientId}
  AND cs.deleted = FALSE
